import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 미리보기 지원 형식은 HWP·Word·Excel·PPT 확장자 (소문자 비교)
const PREVIEW_EXTS = ['hwp', 'hwpx', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];

// 가정: ECM 저장소 조회·변환 모듈이 허용 import에 없어 변환은 연결 전까지 실패로 처리한다
async function convertPreview(ecmFileKey: string, fileExt: string): Promise<string> {
  // TODO: ecm_file_key로 저장소 파일을 조회해 미리보기 형식으로 변환
  throw new ApiError(502, 'PREVIEW_CONVERSION_FAILED', '미리보기 변환에 실패했습니다.');
}

@Controller('api/v1')
export class FnSfr02606Controller {
  @Get('/attachments/:attachmentId/preview')
  async previewAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    checks.queryOf(req.query);
    const rawId = req.params['attachmentId'];
    if (!/^[0-9]+$/.test(rawId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT attachment_id AS "attachmentId",
                file_name AS "fileName",
                file_ext AS "fileExt",
                ecm_file_key AS "ecmFileKey"
           FROM attachment
          WHERE attachment_id = CAST(:attachmentId AS bigint)`,
        { attachmentId: rawId },
      );
      if (rows.length === 0 || !rows[0].ecmFileKey) {
        throw new ApiError(404, 'ATTACHMENT_NOT_FOUND', '첨부파일을 찾을 수 없습니다.');
      }
      const row = rows[0];
      const ext = String(row.fileExt ?? '').replace(/^\./, '').toLowerCase();
      if (!PREVIEW_EXTS.includes(ext)) {
        throw new ApiError(422, 'PREVIEW_UNSUPPORTED_FORMAT', 'HWP, Word, Excel, PPT 형식만 미리보기할 수 있습니다.');
      }
      const previewContent = await convertPreview(String(row.ecmFileKey), ext);
      return {
        attachmentId: Number(row.attachmentId),
        fileName: row.fileName,
        fileExt: row.fileExt,
        previewContent,
      };
    });
  }
}

