import { useState } from 'react';
import {
  call,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02606Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 미리보기한 결과를 목록으로 둔다
  const [results, setResults] = useState<Row[]>([]);
  const [opening, setOpening] = useState(false);
  const [selected, setSelected] = useState<Row | null>(null);
  const [attachmentId, setAttachmentId] = useState<number | string>('');

  async function submit() {
    if (attachmentId === '' || attachmentId === undefined) {
      throw new Error('첨부파일을 선택하세요.');
    }
    const res = await call('GET', `/attachments/${attachmentId}/preview`, role);
    setResults((prev) => [res, ...prev.filter((r) => r.attachmentId !== res.attachmentId)]);
    setOpening(false);
    setAttachmentId('');
    setSelected(res);
    notify('미리보기를 불러왔습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>미리보기 건수</h2>
        <Tiles items={[['이번 조회', results.length]]} />
      </section>
      <section className="box span-12">
        <h2>미리보기 내역</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setOpening(true)}>
            문서 미리보기
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'attachmentId', label: '첨부파일 ID' },
            { key: 'fileName', label: '파일명' },
            { key: 'fileExt', label: '확장자' },
          ]}
          rows={results}
          onRowClick={(row) => setSelected(row)}
          empty="미리보기한 첨부파일이 없습니다."
        />
      </section>
      {opening && (
        <Drawer title="문서 미리보기" onClose={() => setOpening(false)}>
          <Form onSubmit={submit} submit="미리보기">
            <Field label="첨부파일 ID" required>
              <LookupSelect
                table="attachment"
                role={role}
                value={attachmentId}
                onChange={setAttachmentId}
              />
            </Field>
          </Form>
        </Drawer>
      )}
      {selected && (
        <Drawer title="미리보기 내용" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['파일명', String(selected.fileName ?? '')],
              ['확장자', String(selected.fileExt ?? '')],
              ['변환된 미리보기 내용', <pre>{String(selected.previewContent ?? '')}</pre>],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
